-- State transitions declared for RepairOrder: an undeclared move is refused.
-- Generated by metaphor-schema

CREATE OR REPLACE FUNCTION manufacturing.repair_orders_status_transition_check() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
    IF NEW."status" IS DISTINCT FROM OLD."status" AND NOT (
           (COALESCE(OLD."status"::text, ''), COALESCE(NEW."status"::text, '')) IN (('confirmed', 'cancel'), ('confirmed', 'under_repair'), ('draft', 'cancel'), ('draft', 'confirmed'), ('draft', 'under_repair'), ('under_repair', 'cancel'), ('under_repair', 'done'))
       ) THEN
        RAISE EXCEPTION 'state_transition_not_declared: repair_orders.status % -> %', OLD."status", NEW."status"
            USING ERRCODE = 'check_violation', COLUMN = 'status', CONSTRAINT = 'tg_repair_orders__state_transition_not_declared';
    END IF;
    RETURN NEW;
END $$;

DROP TRIGGER IF EXISTS repair_orders_status_transition_check ON manufacturing.repair_orders;
CREATE TRIGGER repair_orders_status_transition_check
    BEFORE UPDATE OF "status" ON manufacturing.repair_orders
    FOR EACH ROW EXECUTE FUNCTION manufacturing.repair_orders_status_transition_check();
